#!/usr/bin/env python3
"""Static release gate for LocalGPT provider-qualified Council and Benchmark Council wiring."""
from __future__ import annotations

import argparse
import re
from pathlib import Path


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", type=Path, required=True)
    args = parser.parse_args()
    root = args.root.resolve()

    checks: list[tuple[str, bool]] = []

    def text(relative: str) -> str:
        path = root / relative
        checks.append((f"file exists: {relative}", path.is_file()))
        return path.read_text(encoding="utf-8") if path.is_file() else ""

    def csharp_parts(relative_without_extension: str) -> str:
        logical = root / relative_without_extension
        paths = sorted(logical.parent.glob(logical.name + "*.cs"))
        checks.append((f"logical C# type exists: {relative_without_extension}", bool(paths)))
        return "\n".join(path.read_text(encoding="utf-8") for path in paths)

    def component_parts(relative_without_extension: str) -> str:
        logical = root / relative_without_extension
        razor = logical.with_suffix(".razor")
        codebehind = sorted(logical.parent.glob(logical.name + "*.razor.cs"))
        paths = ([razor] if razor.is_file() else []) + codebehind
        checks.append((f"logical Razor component exists: {relative_without_extension}", bool(paths)))
        return "\n".join(path.read_text(encoding="utf-8") for path in paths)

